mapper.select:
SELECT t2.`name` AS version_name, t2.unit_value, t4.short_name AS supplier_name, t5.nickname AS creator_name, t1.id, t1.`name`, t1.version_id, t1.inbound_price, t1.one_price, t1.supplier_id, t1.note, t1.create_time, t1.update_time, t1.creator, t1.updater FROM zc_product t1 LEFT JOIN zc_product_version t2 ON t1.version_id = t2.id AND t2.deleted = 0 LEFT JOIN zc_supplier t4 ON t1.supplier_id = t4.id AND t4.deleted = 0 LEFT JOIN system_users t5 ON t1.creator = t5.id AND t5.deleted = 0 WHERE t1.deleted = 0
AND t1.`name` LIKE CONCAT('%', #{reqVO.name}, '%')
AND t1.version_id = #{reqVO.versionId}
AND t1.supplier_id = #{reqVO.supplierId}
AND t1.create_time BETWEEN #{reqVO.createTime[0]} AND #{reqVO.createTime[1]}
ORDER BY t1.id DESC
